// v23.26 (arcfixb), from the review of the arcade core: EVERY DIAL IS PUT BACK WHEN THE ARCADE IS LEFT. The sandbox kept his profile
// aside but not the live dials (CFG), and only the two arcade overlay dials were put back at leave. A guest who opened Settings
// from the pause box (damage, kid mode, volume, text size, a preset) or moved a tuning console slider changed the live dials, and
// the save at leave wrote every one of them into his profile. Now the whole set of dials is copied when the sandbox goes on and
// put back in place (keys added in the arcade removed) before that save, and the volume is applied again.
function arcadeCfgCopy(c){ var o={}, k; for(k in c) if(Object.prototype.hasOwnProperty.call(c,k)) o[k]=(c[k]&&typeof c[k]==='object')?JSON.parse(JSON.stringify(c[k])):c[k]; return o; }
function arcadeCfgPut(o){
  var k;
  for(k in CFG) if(Object.prototype.hasOwnProperty.call(CFG,k)&&!Object.prototype.hasOwnProperty.call(o,k)) delete CFG[k];
  for(k in o) if(Object.prototype.hasOwnProperty.call(o,k)) CFG[k]=o[k];
  return true;
}
function arcadeSandboxIn(role){
  if(ARCADE.on) return false;

  ARCADE.cfg0=null;
}
if(ARCADE.cfgAll){ arcadeCfgPut(ARCADE.cfgAll); ARCADE.cfgAll=null; try{ volApply(); }catch(_va){} }   // v23.26 (arcfixb): every dial as it was before the arcade
ARCADE.on=0;

check:
{v:'VER',what:'from the arcade core review: a dial changed during an arcade session (a Settings row, a preset that puts a new set of dials in place, a tuning slider, a dial added) is put back when the arcade is left, so the dials and his save hold every dial as it was before the arcade',
 run:function(){
   var bad=[], c0=null, o0=null, k, a, b, js, sp, ed0, ex=[];
   try{
     __topClear(); __runPrep();
     if(typeof arcadeSandboxIn!=='function'||typeof arcadeSandboxOut!=='function'||typeof ARCADE!=='object') return 'no arcade in this build';
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     o0=CFG; c0={}; for(k in CFG) if(Object.prototype.hasOwnProperty.call(CFG,k)) c0[k]=CFG[k];
     ed0=CFG.eDmg;
     if(!arcadeSandboxIn('host')) return 'arcadeSandboxIn failed';
     arcadeCfgIn();
     CFG.eDmg=0.137; CFG.zzArcLeak=7;
     applyCfg(DEF,null); CFG.eDmg=0.271; CFG.zzArcLeak2=9;
     arcadeSandboxOut();
     if(ARCADE.on) bad.push('the sandbox is still on');
     if(CFG.eDmg!==ed0) bad.push('the enemy damage dial changed in the arcade is '+CFG.eDmg+' after leaving (it was '+ed0+')');
     if(Object.prototype.hasOwnProperty.call(CFG,'zzArcLeak')||Object.prototype.hasOwnProperty.call(CFG,'zzArcLeak2')) bad.push('a dial added in the arcade is still there after leaving');
     for(k in c0) if(Object.prototype.hasOwnProperty.call(c0,k)){ a=c0[k]; b=CFG[k]; if(a!==b&&JSON.stringify(a)!==JSON.stringify(b)) ex.push(k); }
     for(k in CFG) if(Object.prototype.hasOwnProperty.call(CFG,k)&&!Object.prototype.hasOwnProperty.call(c0,k)) ex.push('+'+k);
     if(ex.length) bad.push(ex.length+' dials not as they were before the arcade: '+ex.slice(0,6).join(', '));
     js=null;
     if(!(window.storage&&window.storage.set)&&!SAVE_STALE){ try{ js=localStorage.getItem(SKEY); }catch(_g){ js=null; } }
     if(js){ sp=null; try{ sp=JSON.parse(js); }catch(_p){ sp=null; } if(sp&&sp.cfg&&sp.cfg.eDmg!==ed0) bad.push('his save holds the enemy damage dial set in the arcade ('+sp.cfg.eDmg+')'); }
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(c0){ CFG=o0; for(k in CFG) if(Object.prototype.hasOwnProperty.call(CFG,k)&&!Object.prototype.hasOwnProperty.call(c0,k)) delete CFG[k]; for(k in c0) if(Object.prototype.hasOwnProperty.call(c0,k)) CFG[k]=c0[k]; saveProfile(); } }catch(_r){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
